}
// ADITIVO. Monto con moneda: pdMonto(55) -> «55 Bs»; pdMonto(12.5, 'BOB') -> «12,50 Bs»; pdMonto(3, 'USD') -> «3 USD».
function pdMonto(n, moneda) {
