  };
}

// ---------------------------------------------------------------------------
// Fechas y horario (America/La_Paz)
// ---------------------------------------------------------------------------
function _vmPad2(n) { return (n < 10 ? '0' : '') + n; }
function _vmEsFecha(f) {
