    generationConfig: {
      responseMimeType: 'application/json',
      maxOutputTokens: 400,
      responseSchema: {
        type: 'OBJECT',
        properties: {
          lineas: {
            type: 'ARRAY',
            items: {
              type: 'OBJECT',
              properties: {
                producto: { type: 'STRING' },
                cantidad: { type: 'INTEGER' },
                // Sin '' en el enum: Gemini rechaza un enum con cadena vacia (400) y sin extraccion no hay pedido.
